#include <iostream>
using namespace std;

int fibonacci(int n) {
    if (n <= 0) {
        cout << "Input should be a positive integer." << endl;
        return -1; // Return an error value
    }
    else if (n == 1) {
        return 0;
    }
    else if (n == 2) {
        return 1;
    }
    else {
        return fibonacci(n-1) + fibonacci(n-2);
    }
}

int main() {
    cout << fibonacci(10) << endl;
    return 0;
}
